#include <iostream>
#include <vector>
#include <cmath>
#include <algorithm>
#include <iomanip>
using namespace std;

int main(){
vector<double>x={0.01,0.02,-0.01,0.03,0.02,0,0.01};int n=x.size(),lag=2;double mean=0,lrVar=0;
for(double v:x)mean+=v/n;
for(int h=0;h<=lag;h++){double gamma=0;for(int t=h;t<n;t++)gamma+=(x[t]-mean)*(x[t-h]-mean)/n;lrVar+=(h==0?1.0:2.0*(1.0-double(h)/(lag+1)))*gamma;}
cout<<fixed<<setprecision(8)<<sqrt(max(0.0,lrVar/n))<<"\n";
return 0;
}

